class Solution {
    public int numberOfBeams(String[] bank){
        int previous=0,answer=0;
        for(String row:bank){
            int current=0;
            for(int i=0;i<row.length();i++)if(row.charAt(i)=='1')current++;
            if(current>0){
                answer+=previous*current;
                previous=current;
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun numberOfBeams(bank:Array<String>):Int{
        var previous=0;
        var answer=0;
        for(row in bank){
            val current=row.count{
                it=='1'
            };
            if(current>0){
                answer+=previous*current;
                previous=current
            }
        };
        return answer
    }
}

code.cpp:
class Solution {
    public:int numberOfBeams(vector<string>& bank){
        int previous=0,answer=0;
        for(string& row:bank){
            int current=count(row.begin(),row.end(),'1');
            if(current){
                answer+=previous*current;
                previous=current;
            }
        }
        return answer;
    }
};
